        targeted_s1 = 0.0

    nm.marketing.set_daily_spend(operations=ops_spend, development=global_dev)
    if targeted_s1 > 0:
        nm.analytics.set_targeted_dev_spend(targeted_spend={"S1": targeted_s1})
    else:
        nm.analytics.set_targeted_dev_spend(targeted_spend={})

    total_dev = global_dev + targeted_s1
    return ops_spend, total_dev

