        # content_marketing: 172.6 leads/1k -> primary driver
        # referral_program: 138.2 leads/1k -> primary driver
        add_spend("content_marketing", "S1", 35.0)
        add_spend("referral_program", "S1", 35.0)

    nm.marketing.set_targeted_ad_spend(targeted_spend=spend_dict)
    return spend_dict

